sys_variable_value.value:
(function execute(inputs, outputs) {

    var currentRecord = inputs.current;

    var companyCode = inputs.codigoEmpresa;
    var contractNumber = inputs.numeroContrato;
    var bpSubrogante = inputs.bPNumberSubrogante;
    var bpSubrogado = inputs.bPNumberSubrogado;
    var validade = inputs.validadeDesde;
    var validadeFormatada = formatDateToDDMMYYYY(validade);


    var myObj = {
  "CompanyCode": companyCode, //obg
  "ContractNumber": contractNumber, //obg
  //"ContractEndDate": "2026-01-01",        
  //"MonetaryCorrectionIndex": "IPCA", 
  //"BaseYear": "1993",
  "BusinessPartners": [
    {
      "BPNumber": bpSubrogante,
      "BPRoleCode": "TR0600", //fixo
      "BPValidTo": validadeFormatada //mudar desse subrogante
    },
    {
      "BPNumber": bpSubrogado,
      "BPRoleCode": "TR0600",      
      "BPValidFrom": validadeFormatada  //mudar pra esse subrogado
    }
  ],
  "TermPayments": [ //obrigatório
    {
      "TermNumber" : "",
      "BPNumber": bpSubrogante, //subrogante
      "ValidTo": validadeFormatada,
      //"ValidFrom": "2024-12-31" 
    },
    {
      "TermNumber" : "",
      "BPNumber": bpSubrogado, //sugrogado
      "ValidFrom": validadeFormatada
    }
  ]
};

//  function formatDateToYYYYMMDD(dateString) {
//     var parts = dateString.split('/');
//     var day = parseInt(parts[0], 10);
//     var month = parseInt(parts[1], 10) - 1; 
//     var year = parseInt(parts[2], 10);

//     var date = new Date(year, month, day);
//     date.setDate(date.getDate() + 1); 

//     var newDay = String(date.getDate()).padStart(2, '0');
//     var newMonth = String(date.getMonth() + 1).padStart(2, '0'); 
//     var newYear = date.getFullYear(); 

//     return `${newYear}-${newMonth}-${newDay}`;
// }

function formatDateToDDMMYYYY(dateString) {
    var parts = dateString.split('/');
    var day = parts[0];
    var month = parts[1];
    var year = parts[2];

    return year + '-' + month + '-' + day;
}

gs.info(validadeFormatada); 

   gs.info('***Integra+ '+ JSON.stringify(myObj));
    outputs.payloadbasic = myObj;

})(inputs, outputs);

